{
  "world_setting": {
      "role_playing": {
         "protagonist": "许七安",
          "description": "{{user}} 将扮演许七安，所有的故事进展、剧情互动、以及人物对话，都将以许七安的视角出发。{{user}} 将做出许七安可能会做的决策，并承担相应的后果。{{user}} 将体验许七安的情感，包括对不同人物的感受、对事件的看法等等。{{user}} 可以运用许七安所具备的能力，如刑侦推理、现代知识、修行技巧等等。"
      },
    "dynasty": {
      "name": "大奉王朝",
      "government": {
        "structure": "皇权集中，皇帝元景帝拥有绝对权威，但实际治理依赖文武百官共同维持。",
        "central_power": {
          "emperor": "元景帝，拥有绝对权威，但依赖百官治理。",
          "palace_politics": "宫廷内权力斗争激烈，存在不同派系如皇后党、陈贵妃党等。",
          "monitoring": "设有六部（吏、户、礼、兵、刑、工）及“打更人”组织，由宦官魏渊统领，直接向皇帝汇报。"
        },
        "local_power": {
          "administration": "地方设有知府、县令等职位，负责具体行政事务。",
          "challenges": "中央与地方信息不对称导致某些地区出现贪腐或管理不善。"
        }
      },
      "society": {
        "classes": {
          "aristocracy": "贵族享有世袭爵位和大量土地，通过联姻巩固地位，并对平民施加限制。",
          "scholar_officials": "普通百姓可通过科举考试进入仕途，成为官员，这是选拔人才的重要手段。",
          "women": "女性在家庭中有一定影响力，但在公共领域受诸多约束，婚姻多由父母安排。"
        },
        "legal_system": {
          "laws": "律法严苛，如谋反者全家抄斩，对普通民众不利。",
          "corruption": "权贵子弟往往逃避法律制裁，司法腐败现象严重。"
        }
      }
    },
    "cultivation_system": {
      "schools": {
        "martial_artist": {
          "description": "分为九品到一品，七品炼神境可使用强大武技，六品铜皮铁骨具备极强防御力。",
          "levels": ["九品", "八品", "七品", "六品", "五品", "四品", "三品", "二品", "一品"]
        },
        "warlock": {
          "description": "以望气术、风水堪舆为主，分为九品至六品多个层次，擅长预测未来，利用自然力量施展法术。",
            "levels": ["九品", "八品", "七品", "六品"]
        },
        "confucianism": {
          "description": "强调修身养性，注重道德修养和个人品格提升，随着境界提高，能逐渐掌握言出法随的能力。"
        },
        "buddhism": {
          "description": "追求心灵净化和觉悟，提倡见性即佛的理念。通过禅定和参悟佛法增强修为。"
        },
        "daoism": {
          "description": "包括内丹外丹等多种修炼方式，追求长生不老乃至飞升成仙。存在双修流派。"
        },
        "gu_master_witch": {
          "description": "来自边疆少数民族的传统修行者，擅长毒药、咒术等非正统手段，在中原地区被视为异端。"
        }
      },
      "tools": {
        "earth_book_fragments": "神秘物品，连接多个持有者形成隐秘交流网络，传递文字消息并影响使用者命运。",
        "rebirth_pill": "司天监特制灵丹妙药，服用后体质发生巨大变化，获得新生。使用条件苛刻，稍有不慎便可能导致死亡。",
        "indestructible_body_technique": "强大的护体神功，接近小成时可以催生出护体气罩，不再是肉身硬抗攻击。"
      },
      "paranormal_phenomena": {
        "sangpo_lake_seal": "传说中被封印于桑泊湖底部的强大物品，其真实性质未明，可能隐藏重要秘密。",
        "spiritual_dragon": "神秘生物，特定情况下表现出攻击性。对某些人物特别敏感，暗示更大阴谋。",
        "six_desires_river_crab_method": "来自蛊族的强大秘术，涉及欲望控制等内容。",
        "fortune": "无形的力量，象征一个人或家族的命运。可以被窃取、转移，甚至镇压。",
          "black_lotus": "邪恶的超自然现象，能在关键时刻产生巨大影响，象征堕落和邪恶，改变人的性格和命运。"
      }
    },
      "technology":{
          "description":"古代科技与现代知识碰撞",
          "scientific_application":"许七安凭借前世记忆引入许多先进科学技术，如电压控制、金属钠提取、玻璃制造等",
          "traditional_technologies":"大奉掌握了火药、火铳、香皂、纸张、水泥等实用发明",
          "alchemy":"炼金术师掌握制作各种法器的技术，如弩、剑、火铳等。"
      },
     "main_characters": {
          "xu_qi_an":{
            "identity": "穿越者，打更人，后成为监正弟子",
              "description": "原为现代社会警校毕业生，因意外穿越到大奉朝。利用现代刑侦技术和科学原理解决案件。",
               "relationship":{
                   "family": {
                       "uncle":"二叔许平志，御刀卫七品绿袍军官",
                       "cousin":"堂弟许新年，举人出身，就读云鹿书院"
                   },
                   "friends": [
                       "褚采薇（司天监监正弟子，擅长炼金术）",
                       "李玉春（打更人成员）",
                        "楚元缜（状元郎）",
                       "钟璃（术士）"
                   ],
                   "mentors": [
                       "魏渊（大宦官，浩气楼居住）",
                       "监正"
                   ],
                   "partners":[
                       "杨砚（魏渊义子）",
                        "南宫倩柔（魏渊另一位义子）",
                         "金莲道长（道士）",
                       "度厄罗汉（佛门高僧）"
                   ],
                    "nobles": [
                       "元景帝（皇帝）",
                        "怀庆公主",
                       "陈贵妃",
                        "淮王(元景帝弟弟）"
                   ],
                    "others":[
                        "浮香（花魁）",
                        "恒远大师（和尚）",
                        "国师洛玉衡",
                        "丽娜（蛊族少女）",
                        "王思慕（贵族小姐）",
                       "宋卿（司天监炼金术师）",
                        "郑布政使"
                    ]
               }
        }
     },
    "plot_development": {
      "initial_challenges": "许七安被困在京兆府大牢，通过回忆前世经验，找出真相并改变现状。",
        "tax_silver_case": "破解税银案，发现税银被人掉包成金属钠。",
        "family_harmony": "家庭成员之间关系得到改善，同事们对许七安表示钦佩。",
        "brothel_life": "工作之余，偶尔去勾栏听曲放松，思考赚钱计划。",
        "bureaucracy_revelation": "揭露官场上的黑暗面，认识到要改变现状需要付出更多努力。",
        "special_events_challenges": [
            "逛街时遭遇恶少调戏妹妹，凭借自身实力反击并获得司天监支持",
            "参与审讯杨珍珍一案，巧妙运用心理学技巧使对方承认罪行",
            "参与调查威武侯女儿张玉英被绑架事件",
            "皇室祭祖期间，在桑泊湖附近听到诡异求救声",
             "处理恒远大师相关案件，发现更多关于桑泊底下封印物的秘密",
            "遇到名为“恒慧”的和尚，此人与平阳郡主私奔",
             "调查赵县令死亡案件，揭开工部尚书私通巫神教",
             "参与云州巡抚任务",
              "在西域使者团来访时，被选为与佛门高僧斗法人选",
              "接触到“六欲大河蟹法”"
        ],
          "fortune_secret": "逐渐意识到体内气运的存在，推测这可能是他在关键时刻化险为夷的原因。",
          "alchemy_advancement": "司天监为了复制制造假银技术不断尝试却屡次失败，直到许七安提供了关于电压控制的关键信息。",
          "heart_question_test": "参加打更人资格测试，经历严格的“问心关”， 以一首诗句表达对于权力与责任看法。",
          "heaven_earth_society": "地书碎片持有人加入名为“天地会”的秘密组织， 地书聊天群不仅是信息交换的地方，也是一个展现个人魅力和智慧舞台。"

    }
  }
}

entries.content:
{
  "world_name": "大奉",
  "dynasty": "大奉王朝",
  "capital": "京城",
    "government": {
        "type": "封建王朝",
        "structure": [
           "皇室: 拥有至高权力，皇帝直接下令。",
            "六部： 负责管理国家行政事务，例如户部（管理财政），刑部（管理司法）。",
            "京兆府：管理京城地区，下辖各县衙，负责地方治安。",
             "御刀卫：负责押运税银，具有军事职能。",
             "打更人：皇室的情报组织，负责侦察、逮捕、审问等活动，也收集军情。",
           "司天监：负责天文、历法、气象等，也有一些特殊能力（如望气术，炼金术）",
              "国子监： 官方设立的儒家学院，与云鹿书院在儒家正统上有所竞争",
             "刑部：负责管理司法，审理案件，拥有逮捕权。",
             "户部：掌管天下钱粮的部门",
            "都察院：负责监察百官",
            "礼部：负责管理教坊司，以及大奉的礼仪",
            "大理寺：负责复审案件"
          ],
       "officials": {
            "官品": "正一品至从九品",
            "官服":{
                "正四品": "绯袍，绣云雁" ,
                  "八品武官": "绿袍",
                "刑部官员":"青袍，绣白鹇",
                "户部官员":" 靛青色袍子",
                  "儒衫":"月白色儒衫，布满浅灰色云纹",
                   "快手":"黑色为底，袖口和领口有着红色滚边的捕快服",
                 "勋贵":"天青配烟紫纹绣袍子，腰间系着镂刻螭纹的白玉带",
                "打更人":"黑色制服，胸口绑着一面铜锣，背后有短披风",
                "打更人(银锣)":"胸口绣银锣的黑色制服",
                  "打更人(金锣)":"胸口绣金锣的黑色制服",
                 "打更人(白衣)":"胸口绣着相应标识的白色制服",
                   "大太监": "穿着蟒袍、头戴乌纱帽，跟在皇帝身边"
               }
          },
      "court_mechanism":{
        "京察":"大奉京官考核制度，三年一查，以‘四格"、‘八法"为升降标准"
        },
      "local_government":{
            "county_level":{
                 "name": "长乐县",
                "description": "京城的附郭县，县衙位于城内",
                 "officials":[
                     "知县：县级最高行政长官。",
                     "县丞：知县的副手。",
                    "主簿：知县的副手。",
                      "典史：又称首领官，没有品级，不入流."
                    ],
             "law_enforcement": [
                      "三班：皂班、快班、壮班，负责仪仗、治安、缉捕等",
                       "快手：也叫捕快，负责缉捕，属于快班。",
                     "白役：临时工，属于徭役，由百姓组成，无工资，负责协助官府工作。"
                     ]
                 }
            }
   },
    "architecture":{
        "description": "建筑风格具有明显的古代特征， 结合了中原地区的传统文化，例如 青楼等建筑，大多是木质结构。",
         "examples":{
           "观星楼":"司天监的办公地点，楼顶为八角形的平台，名为八卦台。",
              "绵羊亭":"郊外送别之地",
            "刑部大牢": "关押犯人的监狱，阴暗潮湿",
           "御刀卫府邸": "御刀卫的办公地点和居住地",
             "长公主府":"长公主的府邸",
            "云鹿书院":"清云山上的书院，大奉儒家圣地",
             "亚圣学宫":"云鹿书院内，供奉着亚圣的宫殿",
          "private_residences": "通常为有身份的人所有， 且会有专门的下人进行管理",
              "浩气楼": "打更人衙门最高的建筑，也叫核心区域",
           "教坊司":"官办妓院，由礼部管辖",
            "宝器轩":"京城一家有名的首饰铺",
              "灵宝观":"道门人宗的所在",
              "Sangbo":"皇城外的小湖，祭祖的场所，湖中心有汉白玉高台，有座永镇山河庙",
           "Yingmei_Pavilion": "教坊司里浮香花魁的住所"
           }
      },
    "geography": {
       "cities": [
           {
             "name": "京城",
                "description": "大奉的首都，繁华热闹，人口众多，是政治、经济、文化的中心。",
                "landmarks": ["广南街","康平街", "绵羊亭","摘星楼", "长公主府", "城隍庙","宝器轩", "教坊司", "桑泊", "御刀卫营地", "灵宝观"]
              }
           ],
       "regions":{
             "border": "边陲之地，荒凉，气候恶劣，流放犯人的地方。",
              "mountains": "南疆十万大山，万妖国的聚居地",
              "holy_land":"清云山，云鹿书院所在",
               "other_mountain":"大黄山，有硝石矿"
             },
       "city_structure":{
            "description":"京城分为宫城，皇城，内城和外城，内城住的都是有身份的人，外城则更为热闹"
            }
     },
    "religion":{
        "Confucianism":{
           "description":"大奉的主流思想",
             "figures":["圣人","亚圣"]
            },
        "Buddhism":{
           "description": "佛门与儒道并立，于佛寺中供奉佛祖"
           },
       "Taoism":{
            "description":"信奉道尊",
              "sub_organizations":["天宗","地宗", "人宗"]
           }
      },
   "currency":{
      "unit":"两",
      "example":"两白银",
        "sub_unit":"钱",
       "copper_coin": "文",
         "exchange_rate":{
           "1_silver_liang":"8_silver_qian",
             "1_silver_liang":"100_copper_wen"
           }
     },
     "time":{
       "unit": "刻",
       "example": "卯时二刻 (早晨六点半), 辰时一刻，寅时，申初，酉时三刻"
    },
  "language":{
       "description": "通用语言是汉语，以及一些俚语",
        "example_phrases":[
            "大爷的","本官","你大爷的", "真是可笑", "卧槽", "皮一下很开心"
           ]
    }
}

{
  "supernatural":{
       "beings": ["妖物", "妖族"],
       "powers": [
         "妖风：某些修行者拥有刮妖风的能力",
          "望气术：司天监术士可以观测人的'气'" ,
          "炼金术：司天监术士可以炼制金属钠等物质",
          "雷法：司天监术士可以运用雷电之力",
          "儒家德行： 儒家修行体系，具有言出法随，修改规则的能力" ,
         "其他修行体系： 武夫，佛门，道门，儒家，巫师，蛊师"
         ],
        "power_system":{
            "martial_artist":{
               "9th_grade": "炼精境",
               "8th_grade": "炼气境",
               "7th_grade":"炼神境",
                 "6th_grade":"铜皮铁骨境"
             },
         "sorcerer": {
                "9th_grade": "医师",
               "8th_grade":"望气师",
               "7th_grade":"风水师",
                "6th_grade":"炼金术师",
              "4th_grade":"阵师"
            },
          "confucianism":{
              "9th_grade":"开窍",
             "8th_grade":"修身",
            "description":"儒家修习，修的是心境，养的是正气，以浩然正气破除万法",
              "power_description":"拥有言出法随之力"
            },
         "taoism":{
            "description":"分为天宗，地宗，人宗",
              "factions":["天宗","地宗", "人宗"]
           },
          "Buddhism":{
           "description":"修持金刚之身",
           "examples":"有武僧一脉，有独特的修行方式"
        },
        "witchcraft":{
           "description": "蛊师，擅长巫蛊之术；巫师擅长魂魄、咒杀之术",
            "power_description":"可以通过施法，杀人于无形"
           }
         },
      "power_description":{
             "ghost_power": "道门中，修习阴神，可以以元神离体的方式进行侦查。并具备杀人于无形的手段",
             "copper_skin_iron_bones": "武夫的境界，体魄强大，如铜皮铁骨。",
           "spirit_power": "指灵兽、异兽体内蕴含的特殊力量"
          }
    },
  "technology": {
       "level": "古代科技，但炼金术师的存在，使其拥有一些超出古代水平的技术，例如金属钠的提炼",
       "other":{
         "法器":"由阵法师加工过的武器，威力巨大",
            "description": "可以通过炼金术和阵法绘制出来。可以增幅武器的威力，也可以施展一些法术。",
         "example":"铜锣，可以抵挡炼神境高手的全力一击",
            "example2": "军弩，可携带剧毒，能伤害炼神境高手",
         "example3":"玉石小镜，具备储物、传讯等功能"
           }
       },
   "punishments":{
        "刑讯":{
            "description": "古代刑讯手段，对犯人进行残酷折磨和拷打，逼迫其认罪",
           "tools":["铁钉座椅", "钢针","铁锯"]
           },
       "special_punishments": [
            "腰斩：把犯人从腰部砍成两段",
           "流放： 将犯人发配至边疆",
           "死罪： 处以死刑",
          "格杀勿论":"直接当场处死，无需禀告"
         ]
       },
     "terms":{
           "天命之子":"被认为是顺应天命的人",
          "等价交换": "炼金术不变的原则",
           "先下手为强":"先行动可以占据优势地位",
         "后下手遭殃": "行动慢一步就会陷入被动",
           "君子当三缄其口":"读书人告诫自己，要谨慎言语",
          "以力犯禁":"武者倚仗自身力量，触犯律法",
          "妖丹":"妖族体内精华凝聚而成的丹药",
         "打茶围":"青楼内，客人和花魁吟诗作对的活动",
        "白嫖":"不花钱白白享受服务",
          "飞花令":"古代酒令的一种，以诗词接龙。",
           "收买人心":"通过赏赐，或者其他方式获取他人的忠诚"
      }
 }

{
